messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
Here is the self-contained HTML file containing the 3D racing animation.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 20px;
            width: 100%;
            text-align: center;
            font-family: sans-serif;
            font-size: 24px;
            font-weight: bold;
            color: white;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">RACE START!</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 100;
        const FINISH_LINE_Z = 40;
        const START_LINE_Z = -40;
        const TOTAL_DISTANCE = START_LINE_Z - FINISH_LINE_Z; // 80 units
        const RACE_DURATION = 5000; // ms for one full loop
        const CAR_SCALE = 2.5;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
        camera.position.set(12, 8, -30);
        camera.lookAt(0, 0, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
        dirLight.position.set(20, 50, 20);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 200);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x4CAF50 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(10, 200);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.z = 0; // Centered Z
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(10, 2);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, FINISH_LINE_Z);
        scene.add(finishLine);

        // Finish Line Pillars
        const pillarGeo = new THREE.BoxGeometry(0.5, 4, 0.5);
        const pillarMat = new THREE.MeshStandardMaterial({ color: 0xAAAAAA });
        const leftPillar = new THREE.Mesh(pillarGeo, pillarMat);
        leftPillar.position.set(-5.5, 2, FINISH_LINE_Z);
        scene.add(leftPillar);
        const rightPillar = new THREE.Mesh(pillarGeo, pillarMat);
        rightPillar.position.set(5.5, 2, FINISH_LINE_Z);
        scene.add(rightPillar);

        // Banner
        const bannerGeo = new THREE.BoxGeometry(11, 1, 0.2);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 4, FINISH_LINE_Z);
        scene.add(banner);

        // --- Car Builder ---
        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(1.8, 0.5, 3.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: colorHex });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.75;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.4, 0.4, 1.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.2, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.35, 0.35, 0.2, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                [-0.9, 0.35, 1.2], [0.9, 0.35, 1.2], // Front
                [-0.9, 0.35, -1.2], [0.9, 0.35, -1.2] // Back
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.position.set(...pos);
                wheel.rotation.z = Math.PI / 2;
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Headlights (to show direction)
            const lightGeo = new THREE.BoxGeometry(0.3, 0.2, 0.1);
            const lightMat = new THREE.MeshStandardMaterial({ color: 0xffff00, emissive: 0xffff00 });
            const leftLight = new THREE.Mesh(lightGeo, lightMat);
            leftLight.position.set(-0.5, 0.75, -1.75);
            carGroup.add(leftLight);
            const rightLight = new THREE.Mesh(lightGeo, lightMat);
            rightLight.position.set(0.5, 0.75, -1.75);
            carGroup.add(rightLight);

            // Tail lights
            const tailLightMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000 });
            const leftTail = new THREE.Mesh(lightGeo, tailLightMat);
            leftTail.position.set(-0.5, 0.75, 1.75);
            carGroup.add(leftTail);
            const rightTail = new THREE.Mesh(lightGeo, tailLightMat);
            rightTail.position.set(0.5, 0.75, 1.75);
            carGroup.add(rightTail);

            carGroup.scale.setScalar(CAR_SCALE);
            return carGroup;
        }

        const redCar = createCar(0xFF0033);
        const blueCar = createCar(0x0033FF);

        // Initial Positions
        // X is lane (Red is left lane -2, Blue is right lane +2)
        // Z is track position (Start at START_LINE_Z)
        redCar.position.set(-2, 0, START_LINE_Z);
        blueCar.position.set(2, 0, START_LINE_Z);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        const clock = new THREE.Clock();
        const infoDiv = document.getElementById('info');

        // Helper for easing: Blue leads early, Red overtakes mid, Red wins.
        // t goes from 0 to 1.
        function getPosition(t) {
            // Blue: Fast start, slows down slightly at end
            // Red: Slow start, massive acceleration in middle/end

            // Blue: 0 -> 0.95 (Almost there, but Red passes)
            const blueProgress = t * 0.96;

            // Red: 0 -> 1.0 (Wins)
            // Using a power curve to simulate acceleration
            const redProgress = Math.pow(t, 1.5) * 1.05;

            // Map progress to Z coordinates
            // Z = Start - (Progress * Distance)
            // Note: Z increases as they go "up" the screen if camera looks down Z, 
            // but here Start is -40, Finish is +40. So Z = -40 + (Progress * 80)
            const dist = TOTAL_DISTANCE; // 80

            const blueZ = START_LINE_Z + (blueProgress * dist);
            const redZ = START_LINE_Z + (redProgress * dist);

            return { blueZ, redZ };
        }

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();

            // Loop the race
            let t = (time % RACE_DURATION) / RACE_DURATION;

            // Add a small delay at the start and end for a natural loop feel
            if (t > 0.9) t = 0.9; 

            const { blueZ, redZ } = getPosition(t);

            // Update Car Positions
            redCar.position.z = redZ;
            blueCar.position.z = blueZ;

            // Camera Follow Logic
            // Calculate midpoint between cars
            const midZ = (redCar.position.z + blueCar.position.z) / 2;

            // Move camera to follow
            // We use lerp for smoothness
            const targetCamZ = midZ - 15; // Stay behind them
            camera.position.z += (targetCamZ - camera.position.z) * 0.05;

            // Keep camera looking slightly ahead
            camera.lookAt(0, 0, midZ + 10);

            // Update Text Info
            if (t < 0.1) {
                infoDiv.textContent = "RACE START!";
                infoDiv.style.color = "white";
            } else if (redZ > blueZ && t < 0.8) {
                infoDiv.textContent = "RED CAR OVERTAKES!";
                infoDiv.style.color = "#FF0033";
            } else if (redZ > FINISH_LINE_Z) {
                infoDiv.textContent = "RED CAR WINS!";
                infoDiv.style.color = "#FFD700";
            } else {
                infoDiv.textContent = "BLUE LEADS...";
                infoDiv.style.color = "#0033FF";
            }

            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();

    </script>
</body>
</html>
```
